column4:
{
  maxSingleUploadSize: int;   // Maximum allowable upload size for a single upload (MB)
  maxSingleFileCount: int;      // Maximum allowable file count for a single upload 
}

{
  requestMemberEmail: string;   // E-mail for the member requesting the upload
  zipFileInfo: {
    size: int;                            // Size of the data to be uploaded before compression (MB)
    count: int;                         // Number of original file names to be uploaded
  }
}

[Success]
{
  s3Key: string;                    // The key that will be used to save the uploaded file in S3.
  presignedUrl: string;           // A temporary URL that allows the client to upload the file directly to S3
                                       // The token(ezserver token) must be included in the request when calling this presigned URL for authentication.
}

[Fail - QUOTA_EXCEEDED Error]
{
  errorCode: string;
  message?: string;
  details?: {
    subscription: {          
       totalSize: int;         // Total size of the subscription (MB)
       usedSize: int;         // Currently used size of the subscription (MB)
    };
    maxUploadSize: int;   // Maximum allowable upload size for a single upload
    maxFileCount: int;     // Maximum allowable file count for a single upload
  }
}

{
  requestMemberEmail: string;      // E-mail for the member requesting the upload
  zipS3Key: string;                      // S3 key for the uploaded zip file
  patient: {                               // Patient information 
    chartNo: string;
    lastName?: string;
    firstName?: string;
    middleName?: string;
    gender?: string;
    birthDate?: string;
    email?: string;
    phone?: string;
    mobile?: string;
    zipCode?: string;
    address?: string;
    race?: string;
  };
  images: [                             // Image information
    {
      orgFileName: string;           // ezserver file name                  
      thumbnaiFileName: string;
      metaFileName?: string;

      modality:? string;
      mode?: string;
      acqDateTime?: string;
      kvp?: number;
      mA?: number;
      dose?: number;
    }
  ];
 }
}

