column4:
{
  sender: {
    tenantUID: string;                                  // Unique identifier for the tenant sharing the data
    memberEmail: string;                             // E-mail for the member sharing the data
  };
  receiver: {
     type: "Member" | "Guest";                      // "Member" for registered users or "Guest" for None-member
     tenantUID?: string;                               // Unique identifier for the recipient tenant  
     email?: string;                                     // Email address of the recipient
     password?: string;                                // Encrypted password for guest (if guest) (요구 사항에 사용자 입력 없음)
  };

  title: string;                                             // Title of the shared data
  description?: string;                                    // Description of the shared data (0317 Jin)

  patientId: int;                                           // ID of the patient whose data is being shared
  imageIds: int[];                                         // Array of image Ids for the images being shared

  patientAnonymizationInImage: boolean;         // Whether patient information within the image has been anonymized to pivacy
}

[Fail - QUOTA_EXCEEDED Error]
{
  code: string;             
  message?: string;
  details?: {
    subscription: {          
      monthlyShareLimit: int;           // Monthly share limit
      monthlySharedCount: int;        // Mothly shares made
    };
    maxUploadSize: int;   // Maximum allowable upload size for a share case (MB)
    maxFileCount: int;     // Maximum allowable file count for a share case
  }
}

